\label{thm:main}
Let $k$ be a positive integer, let $G$ be a graph with
$\Delta(G)\le k$, and let $m=|E(G)|$. Then
\begin{equation}\label{eq:main}
\operatorname{bis}(G)\ge
\begin{cases}
\displaystyle\frac{k+1}{2k}\,m,&\text{if $k$ is odd},\\[6pt]
\displaystyle\frac{k+2}{2(k+1)}\,m,&\text{if $k$ is even}.
\end{cases}
\end{equation}
For each $k$, the corresponding coefficient is best possible.

\label{thm:Hall}
A bipartite graph $B$ with parts $L,Q$ has a matching saturating $Q$
if and only if $|N_B(S)|\ge |S|$ for every $S\subseteq Q$.

\label{lem:preferred}
Let $B$ be a bipartite graph with parts $L,Q$, and suppose that $B$
has a matching saturating $L$. For $Q_0\subseteq Q$, put
\begin{equation}\label{eq:preferreddef}
\delta:=\max_{S\subseteq Q_0}\bigl(|S|-|N_B(S)|\bigr).
\end{equation}
Then $B$ has a matching saturating $L$ and leaving exactly $\delta$
vertices of $Q_0$ uncovered. Every matching of $B$ leaves at least
$\delta$ vertices of $Q_0$ uncovered.

\label{thm:GE}
For the sets in~\eqref{eq:GEsets}, the following hold.
\begin{enumerate}
\item Every $T\in\mathcal D$ is factor-critical.
\item The graph $G[R]$ has a perfect matching.
\item Every maximum matching consists of a perfect matching of
$G[R]$, a near-perfect matching within each $T\in\mathcal D$, and edges
joining all vertices of $A$ to the internally exposed vertices of
$|A|$ distinct components in $\mathcal D$.
\end{enumerate}
In particular,
\begin{equation}\label{eq:GEcardinality}
\nu(G)=\frac{n-|\mathcal D|+|A|}{2}.
\end{equation}

\label{lem:pairing}
Suppose that $G$ has even order, and let $M$ be a maximum matching
of size $s$, with exposed vertex set $W$. Let $P_1,\ldots,P_q$
be pairwise disjoint two-element subsets of $W$. Suppose that for
every $i$ there is an edge $xy\in M$ such that
\begin{equation}\label{eq:oddadjacency}
e_G(P_i,\{x,y\})\quad\text{is odd}.
\end{equation}
Then
\begin{equation}\label{eq:pairbound}
\operatorname{bis}(G)\ge\frac m2+\frac{s+q}{2}.
\end{equation}

\label{lem:deficiency}
Let $k$ be an odd positive integer and let $\Delta(G)\le k$.
Then, for $t$ defined in~\eqref{eq:tdef},
\begin{equation}\label{eq:keydef}
\Phi_k(G)\ge kt.
\end{equation}

\label{prop:structural}
Let $G$ have even order $n$ and $m$ edges, and let $t(G)$ be defined
by~\eqref{eq:tdef}. Then
\begin{equation}\label{eq:structural}
\operatorname{bis}(G)\ge\frac m2+\frac{n-t(G)}4.
\end{equation}
